(4514038, 650791, 86447, '<td valign="top">The harsh lighting is washing the photo out and causing this adorable pet to squint.</td>', 'The harsh lighting is washing the photo out and causing this adorable pet to squint.', '2008-02-25 08:10:39.000000', NULL, 1),
(4514040, 650836, 65234, '<td valign="top">Aw, he''s odd-eyed.  Nice job overall; his oranges look a little too saturated on my monitor but that''s a relative nit.</td>', 'Aw, he''s odd-eyed.  Nice job overall; his oranges look a little too saturated on my monitor but that''s a relative nit.', '2008-02-25 08:11:32.000000', NULL, 1),
(4514042, 650829, 86447, '<td valign="top">Dark eyes are hard to photograph and see clearly... his/her eyes are almost blank holes.    In advanced editing, I''d get rid of the flies.</td>', 'Dark eyes are hard to photograph and see clearly... his/her eyes are almost blank holes.    In advanced editing, I''d get rid of the flies.', '2008-02-25 08:11:35.000000', NULL, 1),
