(4518993, 650464, 87328, '<td valign="top">Nice color contrast, DOF and congrats on the pose! One of the best in this challenge.</td>', 'Nice color contrast, DOF and congrats on the pose! One of the best in this challenge.', '2008-02-26 17:41:44.000000', NULL, 1),
(4518997, 650563, 87328, '<td valign="top">Nice contrast with the background. Nice and sharp. Lots of personality in your cat. Only comment would be to reduce the noise in the background a little bit, or blur it up a little bit. But that is small.</td>', 'Nice contrast with the background. Nice and sharp. Lots of personality in your cat. Only comment would be to reduce the noise in the background a little bit, or blur it up a little bit. But that is small.', '2008-02-26 17:43:56.000000', NULL, 1),
(4519003, 650677, 87328, '<td valign="top">Nice skin tone, great composition. Too bad the snakes tongue wasn''t out. But that is a small detail.</td>', 'Nice skin tone, great composition. Too bad the snakes tongue wasn''t out. But that is a small detail.', '2008-02-26 17:46:02.000000', NULL, 1),
(4519007, 649002, 87328, '<td valign="top">Lots of personality! Nice job on contrasting 2 dark colors (background and Black dog) I like the softness of the photo.</td>', 'Lots of personality! Nice job on contrasting 2 dark colors (background and Black dog) I like the softness of the photo.', '2008-02-26 17:47:50.000000', NULL, 1),
(4519010, 649317, 87328, '<td valign="top">Nice DOF with background, I''d hire you.</td>', 'Nice DOF with background, I''d hire you.', '2008-02-26 17:48:49.000000', NULL, 1),
(4519012, 650749, 87328, '<td valign="top">Nice job with color on color, the subject stands out despite being similar in color to the back drop. Unique pet, nice change from the dogs and cats.</td>', 'Nice job with color on color, the subject stands out despite being similar in color to the back drop. Unique pet, nice change from the dogs and cats.', '2008-02-26 17:50:21.000000', NULL, 1),
(4519021, 650359, 87328, '<td valign="top">Great Family shot! I would have moved the darker dogs on the left to the lighter side of the back drop on the right, but if you got them lined up at all you''re doing a lot right as it is!</td>', 'Great Family shot! I would have moved the darker dogs on the left to the lighter side of the back drop on the right, but if you got them lined up at all you''re doing a lot right as it is!', '2008-02-26 17:55:19.000000', NULL, 1),
(4519023, 650887, 87328, '<td valign="top">Unique subject. Mabye just a bit more DOF.</td>', 'Unique subject. Mabye just a bit more DOF.', '2008-02-26 17:56:45.000000', NULL, 1),
