(4522702, 650798, 66952, '<td valign="top">A very handsome cat.</td>', 'A very handsome cat.', '2008-02-27 16:49:56.000000', NULL, 1),
(4522771, 650562, 70896, '<td valign="top">Great shot! I love it when people think outside the box. Good job!</td>', 'Great shot! I love it when people think outside the box. Good job!', '2008-02-27 17:01:19.000000', NULL, 1),
(4522792, 650894, 70896, '<td valign="top">Very pretty image!</td>', 'Very pretty image!', '2008-02-27 17:03:12.000000', NULL, 1),
(4522800, 649647, 70896, '<td valign="top">Cute dog!!!</td>', 'Cute dog!!!', '2008-02-27 17:04:09.000000', NULL, 1),
(4522813, 650068, 70896, '<td valign="top">I wish there was a little more detail on the bottom part of the picture... otherwise great shot! 9</td>', 'I wish there was a little more detail on the bottom part of the picture... otherwise great shot! 9', '2008-02-27 17:05:28.000000', NULL, 1),
