INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4522820, 650068, 90658, '<td valign="top">nice color choices.  perhaps cropping the top a weeny bit will help.</td>', 'nice color choices.  perhaps cropping the top a weeny bit will help.', '2008-02-27 17:06:54.000000', NULL, 1),
(4522821, 650365, 90658, '<td valign="top">I''m wondering if a softer focus would convey "contemplativeness" better.</td>', 'I''m wondering if a softer focus would convey "contemplativeness" better.', '2008-02-27 17:06:59.000000', NULL, 1),
(4522822, 649573, 90658, '<td valign="top">This almost seems like a shot taken outside.  The tubing on the upper right is the only hint that it is an aquarium.</td>', 'This almost seems like a shot taken outside.  The tubing on the upper right is the only hint that it is an aquarium.', '2008-02-27 17:07:06.000000', NULL, 1),
(4522823, 650887, 90658, '<td valign="top">I absolutely love the blue behind the green and brown.  It brings my line of sight directly to the frog.</td>', 'I absolutely love the blue behind the green and brown.  It brings my line of sight directly to the frog.', '2008-02-27 17:07:11.000000', NULL, 1),
(4522825, 650659, 90658, '<td valign="top">The red &amp; green set apart nicely in this shot.</td>', 'The red & green set apart nicely in this shot.', '2008-02-27 17:07:18.000000', NULL, 1),
